class RenderOps(_Area):
    """Renders with Movie Render Queue: image sequences plus the mixed audio, deferred (Lumen) or path-traced, with temporal/spatial samples and console variables for quality."""
    _area = 'render'

    def mrq(self, *, sequence: str, level: str, out_dir: str, width: int = UNSET, height: int = UNSET, temporal: int = UNSET, spatial: int = UNSET, path_tracer: bool = UNSET, quality: bool = UNSET, cvars: dict | None = UNSET, fmt: str = UNSET, warmup: int = UNSET, name: str = UNSET, start: int | None = UNSET, end: int | None = UNSET, executor: str = UNSET, save_dirty: bool = UNSET, _wait: bool = True, _timeout: float = 900) -> dict:
        """Start a Movie Render Queue job (returns at once; poll render.progress). Frames go to `out_dir` as
        {frame}.png|exr|jpg, the audio as a wav; `start`/`end` (end exclusive) render part of the sequence. `executor`:
        "pie" (in this editor) or "process" (a separate -game process; offscreen where the editor has no desktop). The
        process loads the level from disk, and with unsaved changes the executor asks to save first: unattended, that
        question goes unanswered and the job never starts, so unsaved packages are an error unless `save_dirty`.

        Args:
            sequence (str, required)
            level (str, required)
            out_dir (str, required)
            width (int, default 1920)
            height (int, default 1080)
            temporal (int, default 8)
            spatial (int, default 1)
            path_tracer (bool, default false)
            quality (bool, default true)
            cvars (dict | None, default null)
            fmt (str, default "png")
            warmup (int, default 32)
            name (str, default "shot")
            start (int | None, default null)
            end (int | None, default null)
            executor (str, default "pie")
            save_dirty (bool, default false)

        Op: render.mrq  (unreal/fmbridge/ops/render.py:25)
        Returns: dict
        """
        return self._call('render.mrq', {'sequence': sequence, 'level': level, 'out_dir': out_dir, 'width': width, 'height': height, 'temporal': temporal, 'spatial': spatial, 'path_tracer': path_tracer, 'quality': quality, 'cvars': cvars, 'fmt': fmt, 'warmup': warmup, 'name': name, 'start': start, 'end': end, 'executor': executor, 'save_dirty': save_dirty}, _wait, _timeout)

    def progress(self, *, out_dir: str, expected: int = UNSET, _wait: bool = True, _timeout: float = 900) -> dict:
        """Frames written so far (and whether Movie Render Queue is still running).

        Args:
            out_dir (str, required)
            expected (int, default 0)

        Op: render.progress  (unreal/fmbridge/ops/render.py:102)
        Returns: dict
        """
        return self._call('render.progress', {'out_dir': out_dir, 'expected': expected}, _wait, _timeout)


class SeqOps(_Area):
    """Level sequences: a shot from an actor, animations per component, audio and a camera; open and scrub."""
    _area = 'seq'

    def anim(self, *, path: str, label: str, component: str, sections: list, replace: bool = UNSET, _wait: bool = True, _timeout: float = 900) -> list:
        """Animation sections on an actor's skeletal mesh component (a MetaHuman's "Body" or "Face"), each
        {"anim", "start", "end", "offset", "blend_in", "blend_out", "rate", "weight", "loop", "row"}: `start`/`end`
        frames (end default: start + the animation's length / rate; past that it loops, `loop` False holds the last
        pose), `offset` seconds into the animation where it starts, `blend_in`/`blend_out` frames of ease (weights
        cross-fade where sections overlap: idle -> line -> idle), `weight` (1), `row` (default: the first free one; overlaps
        go on separate rows). `replace` clears the track's sections first, else these are added. Returns [[anim, start,
        end, row]].

        Args:
            path (str, required)
            label (str, required)
            component (str, required)
            sections (list, required)
            replace (bool, default true)

        Op: seq.anim  (unreal/fmbridge/ops/seq.py:593)
        Returns: list
        """
        return self._call('seq.anim', {'path': path, 'label': label, 'component': component, 'sections': sections, 'replace': replace}, _wait, _timeout)

    def audio(self, *, path: str, clips: list, track: str = UNSET, replace: bool = UNSET, _wait: bool = True, _timeout: float = 900) -> list:
        """Sounds in a sequence on a named audio track ("VO", "Score", "SFX"): clips [{"sound", "start", "end", "offset",
        "volume"}] or [sound, start]: a SoundWave asset (assets.import a WAV first) from frame `start`, `offset` seconds
        into it, to `end` (default: its length), at `volume` (1). For timing in the editor; the mix is made in post.
        `replace` empties the named track first, else adds to it. Returns [[sound, start, end, row]].

        Args:
            path (str, required)
            clips (list, required)
            track (str, default "Audio")
            replace (bool, default true)

        Op: seq.audio  (unreal/fmbridge/ops/seq.py:663)
        Returns: list
        """
        return self._call('seq.audio', {'path': path, 'clips': clips, 'track': track, 'replace': replace}, _wait, _timeout)

    def camera_cuts(self, *, path: str, cuts: list, _wait: bool = True, _timeout: float = 900) -> list:
        """The edit: cuts are [camera label, first frame] in order; each runs to the next (the last to the end).

        Args:
            path (str, required)
            cuts (list, required)

        Op: seq.camera_cuts  (unreal/fmbridge/ops/seq.py:216)
        Returns: list
        """
        return self._call('seq.camera_cuts', {'path': path, 'cuts': cuts}, _wait, _timeout)

    def close(self, *, _wait: bool = True, _timeout: float = 900) -> bool:
        """Close the open sequence.


        Op: seq.close  (unreal/fmbridge/ops/seq.py:75)
        Returns: bool
        """
        return self._call('seq.close', {}, _wait, _timeout)

    def cuts(self, *, path: str, _wait: bool = True, _timeout: float = 900) -> list:
        """The edit as it stands: [camera label, first frame, end frame] for each camera cut, in order.

        Args:
            path (str, required)

        Op: seq.cuts  (unreal/fmbridge/ops/seq.py:705)
        Returns: list
        """
        return self._call('seq.cuts', {'path': path}, _wait, _timeout)

    def key_collection(self, *, path: str, collection: str, param: str, keys: list, interp: str = UNSET, _wait: bool = True, _timeout: float = 900) -> dict:
        """Key a scalar parameter of a material parameter collection (look.collection) on the sequence's track for that
        collection: keys [[frame, value(, interp)], ...]. Sequencer writes the world's instance of the collection, so the
        value reaches every material reading it with no mesh binding and no MID in between. Replaces only that
        parameter's keys.

        Args:
            path (str, required)
            collection (str, required)
            param (str, required)
            keys (list, required)
            interp (str, default "auto")

        Op: seq.key_collection  (unreal/fmbridge/ops/seq.py:519)
        Returns: dict
        """
        return self._call('seq.key_collection', {'path': path, 'collection': collection, 'param': param, 'keys': keys, 'interp': interp}, _wait, _timeout)

    def key_color(self, *, path: str, label: str, prop: str, keys: list, component: str = UNSET, interp: str = UNSET, srgb: bool | None = UNSET, _wait: bool = True, _timeout: float = 900) -> dict:
        """Key a colour property: keys [[frame, [r, g, b(, a)](, interp)], ...]. An FColor property (a light's
        "LightColor") takes sRGB 0-1, as look.light does; an FLinearColor one (fog "FogInscatteringLuminance", a post
        "Settings.ColorGain") takes linear values. `srgb` overrides that guess. Component and replacement as key_float.

        Args:
            path (str, required)
            label (str, required)
            prop (str, required)
            keys (list, required)
            component (str, default "")
            interp (str, default "auto")
            srgb (bool, default null)

        Op: seq.key_color  (unreal/fmbridge/ops/seq.py:409)
        Returns: dict
        """
        return self._call('seq.key_color', {'path': path, 'label': label, 'prop': prop, 'keys': keys, 'component': component, 'interp': interp, 'srgb': srgb}, _wait, _timeout)

    def key_float(self, *, path: str, label: str, prop: str, keys: list, component: str = UNSET, interp: str = UNSET, double: bool = UNSET, _wait: bool = True, _timeout: float = 900) -> dict:
        """Key a float property of an actor or component: keys [[frame, value(, interp)], ...], interp "auto" (smooth,
        eased at held ends), "linear" or "constant" (stepped). `prop` is the C++ name or a path into structs, either
        spelling: "Intensity", "Temperature", "FocusSettings.ManualFocusDistance" (CameraComponent), "CurrentAperture",
        "Settings.AutoExposureBias" (a PostProcessVolume actor: set its override flag once with look.post), "FogDensity".
        `component` by name or class ("CameraComponent", "LightComponent0"); "" = the actor if it has the property, else
        its root component (a light's). `double` for a double property (a UE5 large-world value). Replaces only this
        property's track on that binding; the keys hold before the first and after the last.

        Args:
            path (str, required)
            label (str, required)
            prop (str, required)
            keys (list, required)
            component (str, default "")
            interp (str, default "auto")
            double (bool, default false)

        Op: seq.key_float  (unreal/fmbridge/ops/seq.py:384)
        Returns: dict
        """
        return self._call('seq.key_float', {'path': path, 'label': label, 'prop': prop, 'keys': keys, 'component': component, 'interp': interp, 'double': double}, _wait, _timeout)

    def key_material(self, *, path: str, label: str, param: str, keys: list, slot: int = UNSET, component: str = UNSET, interp: str = UNSET, _wait: bool = True, _timeout: float = 900) -> dict:
        """Key a material parameter on a mesh component's material slot (the material there must be an instance or
        material with that parameter): keys [[frame, value(, interp)], ...], a float for a scalar parameter or
        [r, g, b(, a)] (linear) for a vector one. `slot` is its index or name ("M_Sheer"); `component` "" = the actor's
        first mesh component. Replaces only that parameter's keys in the slot's track; other parameters keep theirs.

        Args:
            path (str, required)
            label (str, required)
            param (str, required)
            keys (list, required)
            slot (int, default 0)
            component (str, default "")
            interp (str, default "auto")

        Op: seq.key_material  (unreal/fmbridge/ops/seq.py:466)
        Returns: dict
        """
        return self._call('seq.key_material', {'path': path, 'label': label, 'param': param, 'keys': keys, 'slot': slot, 'component': component, 'interp': interp}, _wait, _timeout)

    def key_transform(self, *, path: str, label: str, keys: list, interp: str = UNSET, _wait: bool = True, _timeout: float = 900) -> int:
        """Animate an actor in a sequence: keys are [frame, [x, y, z], {"pitch", "yaw", "roll"} | [x, y, z] to look at]
        with an optional 4th element, the interpolation leaving that key: "auto" (smooth, eases at held ends), "linear"
        or "constant" (hold until the next key, a jump cut). `interp` is the default. Replaces the actor's transform
        track (and only that), keeping the actor's scale; yaw is keyed as given, so unwrap it yourself across +-180.

        Args:
            path (str, required)
            label (str, required)
            keys (list, required)
            interp (str, default "auto")

        Op: seq.key_transform  (unreal/fmbridge/ops/seq.py:192)
        Returns: int
        """
        return self._call('seq.key_transform', {'path': path, 'label': label, 'keys': keys, 'interp': interp}, _wait, _timeout)

    def key_visible(self, *, path: str, label: str, keys: list, component: str = UNSET, attached: bool = UNSET, _wait: bool = True, _timeout: float = 900) -> dict:
        """Show and hide an actor (or one of its components) over a sequence: keys [[frame, visible], ...], stepped; the
        first key holds before it. Overrides the level's hidden state while the sequence is open or playing (a
        presenter hidden in the level can appear in the reel). `attached` keys the actors attached to it too (her
        earrings and watch). Replaces only the visibility track.

        Args:
            path (str, required)
            label (str, required)
            keys (list, required)
            component (str, default "")
            attached (bool, default false)

        Op: seq.key_visible  (unreal/fmbridge/ops/seq.py:433)
        Returns: dict
        """
        return self._call('seq.key_visible', {'path': path, 'label': label, 'keys': keys, 'component': component, 'attached': attached}, _wait, _timeout)

    def new(self, *, path: str, start: int = UNSET, end: int = UNSET, fps: int = UNSET, replace: bool = UNSET, _wait: bool = True, _timeout: float = 900) -> dict:
        """An empty level sequence for building into (no actor, no camera): playback [start, end) at `fps`. If it exists it
        is kept as it is (only its range set), so several scripts can each add their tracks; `replace` starts it afresh.

        Args:
            path (str, required)
            start (int, default 0)
            end (int, default 120)
            fps (int, default 24)
            replace (bool, default false)

        Op: seq.new  (unreal/fmbridge/ops/seq.py:361)
        Returns: dict
        """
        return self._call('seq.new', {'path': path, 'start': start, 'end': end, 'fps': fps, 'replace': replace}, _wait, _timeout)

    def rebind(self, *, path: str, labels: list | None = UNSET, _wait: bool = True, _timeout: float = 900) -> dict:
        """Point a sequence's actor bindings at the level's actors of the same label again, after the level was rebuilt
        and the old actors are gone (their tracks are kept; a binding removed and remade would lose them). `labels` None
        = every actor binding whose name is an actor in the level. Returns {label: "ok" | "missing"}.

        Args:
            path (str, required)
            labels (list | None, default null)

        Op: seq.rebind  (unreal/fmbridge/ops/seq.py:728)
        Returns: dict
        """
        return self._call('seq.rebind', {'path': path, 'labels': labels}, _wait, _timeout)

    def sample(self, *, path: str, actor_label: str, component: str, bones: list, frames: list | None = UNSET, every: int = UNSET, ticks: int = UNSET, camera: str = UNSET, target: Any = UNSET, target_offset: Any = UNSET, _wait: bool = True, _timeout: float = 900) -> Any:
        """Play a sequence frame by frame across editor ticks (so animation and rigs settle) and record bones' world
        transforms, each [x, y, z, axis_x(3), axis_y(3), axis_z(3)], `camera`'s location, and `target`'s (see
        seq.aim_point: a point, an actor, "Label:Component:bone"). A multi-tick job.

        Args:
            path (str, required)
            actor_label (str, required)
            component (str, required)
            bones (list, required)
            frames (list | None, default null)
            every (int, default 1)
            ticks (int, default 2)
            camera (str, default "")
            target (any, default null)
            target_offset (any, default null)

        Op: seq.sample  (unreal/fmbridge/ops/seq.py:138)  multi-tick
        """
        return self._call('seq.sample', {'path': path, 'actor_label': actor_label, 'component': component, 'bones': bones, 'frames': frames, 'every': every, 'ticks': ticks, 'camera': camera, 'target': target, 'target_offset': target_offset}, _wait, _timeout)

    def scrub(self, *, path: str, frame: int, _wait: bool = True, _timeout: float = 900) -> int:
        """Open a sequence in Sequencer, locked to its camera, at a frame (for checking a pose in the viewport).

        Args:
            path (str, required)
            frame (int, required)

        Op: seq.scrub  (unreal/fmbridge/ops/seq.py:66)
        Returns: int
        """
        return self._call('seq.scrub', {'path': path, 'frame': frame}, _wait, _timeout)

    def set_anim(self, *, path: str, component: str, anim: str, label: str = UNSET, only: str = UNSET, _wait: bool = True, _timeout: float = 900) -> str:
        """Swap the animation on a component's track in a sequence: every section of it, or only those playing `only`.
        `label` picks the actor when several have a component of that name (both presenters have "Body").

        Args:
            path (str, required)
            component (str, required)
            anim (str, required)
            label (str, default "")
            only (str, default "")

        Op: seq.set_anim  (unreal/fmbridge/ops/seq.py:93)
        Returns: str
        """
        return self._call('seq.set_anim', {'path': path, 'component': component, 'anim': anim, 'label': label, 'only': only}, _wait, _timeout)

    def shot(self, *, path: str, actor_label: str, anims: dict, camera: str, audio: str = UNSET, seconds: float = UNSET, fps: int = UNSET, audio_start: int = UNSET, tail: int = UNSET, _wait: bool = True, _timeout: float = 900) -> dict:
        """A shot: `anims` maps component names to animations ({"Body": idle, "Face": talk}); `audio` a SoundWave; the
        camera cut on `camera`. Length: `seconds`, else the audio's, else the longest animation's.

        Args:
            path (str, required)
            actor_label (str, required)
            anims (dict, required)
            camera (str, required)
            audio (str, default "")
            seconds (float, default 0.0)
            fps (int, default 24)
            audio_start (int, default 0)
            tail (int, default 6)

        Op: seq.shot  (unreal/fmbridge/ops/seq.py:23)
        Returns: dict
        """
        return self._call('seq.shot', {'path': path, 'actor_label': actor_label, 'anims': anims, 'camera': camera, 'audio': audio, 'seconds': seconds, 'fps': fps, 'audio_start': audio_start, 'tail': tail}, _wait, _timeout)

    def still(self, *, path: str, frame: int, camera: str, out: str, width: int = UNSET, height: int = UNSET, settle: int = UNSET, _wait: bool = True, _timeout: float = 900) -> Any:
        """A still of a sequence at a frame through `camera`, or, with camera "", through the camera the edit (the camera
        cut track) shows at that frame: scrub there, let it settle `settle` ticks (temporal anti-aliasing, Lumen),
        capture. A multi-tick job.

        Args:
            path (str, required)
            frame (int, required)
            camera (str, required)
            out (str, required)
            width (int, default 1920)
            height (int, default 1080)
            settle (int, default 30)

        Op: seq.still  (unreal/fmbridge/ops/seq.py:167)  multi-tick
        """
        return self._call('seq.still', {'path': path, 'frame': frame, 'camera': camera, 'out': out, 'width': width, 'height': height, 'settle': settle}, _wait, _timeout)

    def stills(self, *, path: str, frames: list, camera: str = UNSET, out_dir: str = UNSET, width: int = UNSET, height: int = UNSET, settle: int = UNSET, _wait: bool = True, _timeout: float = 900) -> Any:
        """Stills of a sequence at many frames ({out_dir}/{frame:04d}.png): a contact sheet's worth in one call. Through
        one `camera`, or with camera "" each frame through its own shot's camera (the camera cut track): a previs of the
        whole cut. A multi-tick job; returns [[frame, camera, path]].

        Args:
            path (str, required)
            frames (list, required)
            camera (str, default "")
            out_dir (str, default "")
            width (int, default 960)
            height (int, default 540)
            settle (int, default 20)

        Op: seq.stills  (unreal/fmbridge/ops/seq.py:235)  multi-tick
        """
        return self._call('seq.stills', {'path': path, 'frames': frames, 'camera': camera, 'out_dir': out_dir, 'width': width, 'height': height, 'settle': settle}, _wait, _timeout)

    def tracks(self, *, path: str, _wait: bool = True, _timeout: float = 900) -> dict:
        """What a sequence holds: for each binding (an actor, or actor.component) its tracks as [class, property or
        name, sections, keys]; master tracks under "". For checking what a build script made.

        Args:
            path (str, required)

        Op: seq.tracks  (unreal/fmbridge/ops/seq.py:759)
        Returns: dict
        """
        return self._call('seq.tracks', {'path': path}, _wait, _timeout)


class SpeechOps(_Area):
    """Speech to face: a voice file on the workstation becomes a MetaHuman facial animation (lip-sync, blinks, brows, head movement), through MetaHuman Animator's audio solver with a chosen mood."""
    _area = 'speech'

    def moods(self, *, _wait: bool = True, _timeout: float = 900) -> list:
        """The audio solver's moods (AUTO_DETECT, CONFIDENCE, EXCITEMENT, HAPPINESS, ...).


        Op: speech.moods  (unreal/fmbridge/ops/speech.py:14)
        Returns: list
        """
        return self._call('speech.moods', {}, _wait, _timeout)

    def to_face(self, *, wav: str, name: str, face_mesh: str, mood: str = UNSET, intensity: float = UNSET, head: bool = UNSET, blinks: bool = UNSET, folder: str = UNSET, _wait: bool = True, _timeout: float = 900) -> dict:
        """Import `wav` (a path on the workstation), solve it with MetaHuman Animator's audio solver in `mood` at
        `intensity`, and export an animation on `face_mesh`'s skeleton. Returns the sound, performance and animation.
        A multi-tick job.

        Args:
            wav (str, required)
            name (str, required)
            face_mesh (str, required)
            mood (str, default "CONFIDENCE")
            intensity (float, default 1.0)
            head (bool, default true)
            blinks (bool, default true)
            folder (str, default "/Game/Speech")

        Op: speech.to_face  (unreal/fmbridge/ops/speech.py:20)  multi-tick
        Returns: dict
        """
        return self._call('speech.to_face', {'wav': wav, 'name': name, 'face_mesh': face_mesh, 'mood': mood, 'intensity': intensity, 'head': head, 'blinks': blinks, 'folder': folder}, _wait, _timeout)


AREAS = {'anim': AnimOps, 'assets': AssetsOps, 'level': LevelOps, 'look': LookOps, 'mh': MhOps, 'render': RenderOps, 'seq': SeqOps, 'speech': SpeechOps}
